    $result.Status = 'Failed'
    $result.Error = $_.Exception.Message
    Write-Output $result.Error
} finally {
    $result.Finished = (Get-Date).ToString('o')
    $result | ConvertTo-Json | Set-Content -LiteralPath $resultPath -Encoding UTF8
    Stop-Transcript
}

